import math

def test_k():
    # We want to see if there is any (u, v) such that c/d is in (3-2*sqrt(2), 3+2*sqrt(2))
    # c/d = v*(u-v) / (u*(u+v))
    # This would mean c^2+d^2/cd < 6.
    for u in range(2, 2000):
        for v in range(1, u):
            c_over_d = (v * (u - v)) / (u * (u + v))
            if 3 - 2 * math.sqrt(2) < c_over_d < 3 + 2 * math.sqrt(2):
                print(f"Found c/d = {c_over_d} for u={u}, v={v} which is in the range!")
                return
    print("No such u, v found.")

test_k()
